"""Build the manager guide and its separate one-page quick-reference section."""
from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,PageBreak,Table,TableStyle,KeepTogether
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors

ROOT=Path(__file__).resolve().parents[1]
TOPICS=[
 dict(title='Project introduction',purpose='Explain the business purpose before discussing the software.',screen='Sign in → Dashboard',steps=['Open http://127.0.0.1:8000 and sign in with an authorized demo account.','Click Start Guided Demo. The walkthrough selects the primary synthetic cable case.'],question='What does this project do?',expected='A synthetic, read-only walkthrough with twelve explained steps.',say='We compare a quotation with comparable historical purchases, build a defensible negotiation position and preserve the evidence for human review.',proposal='Sections 1, 3 and 5: one coordinated six-stage decision-support agent.',limits='This is a synthetic pilot. It is not actual BSES history, guaranteed savings or contractual acceptance.'),
 dict(title='Dashboard',purpose='Give management a short view of work awaiting attention.',screen='Dashboard',steps=['Read Procurement cases, Pending reviews, Potential opportunity and Cases requiring attention.','Open a recent case, or use View all procurement cases. Start Guided Demo begins the recommended demonstration.'],question='Which case should we review?',expected='Four database-backed indicators and five recent cases; all authorized cases remain in the case selector.',say='The dashboard tells us where to focus. It does not replace the underlying evidence or the reviewer’s decision.',proposal='Sections 3 and 5.2: a negotiation cockpit and review-oriented user experience.',limits='Opportunity is an estimate, not realized savings. Different currencies are not added together.'),
 dict(title='Data sources',purpose='Show where the historical evidence came from.',screen='Supplier & Evidence → Retained source files',steps=['Choose the demonstration case in Selected procurement case.','Click Retained source files, then Download original source to inspect the protected retained file.','Authorized data users can open Settings / Administration → Data import for validation errors, column mapping and dataset freeze.'],question='Show the evidence.',expected='Source file names, captured dates and integrity hashes linked to the case’s historical comparables.',say='This example uses retained synthetic procurement observations. Source identifiers, dates and original values remain available for review.',proposal='Sections 4 and 4.2: controlled evidence, source identity and traceability.',limits='A hash proves retained-file integrity; it does not independently authenticate a real business source. Paid feeds are disabled.'),
 dict(title='Historical price benchmarking',purpose='Compare technically and commercially eligible purchases.',screen='Price Benchmarking → Historical comparables and normalization',steps=['Select the primary demonstration case.','Expand Historical comparables and normalization to see the first five eligible records.','Use Expand complete comparable set to inspect all included records. Open Technical Details for exclusions and transformations.'],question='Compare historical purchases.',expected='Recorded historical prices normalized to the quotation’s unit, with source references and observation dates.',say='Only eligible purchases support this position. A similar description alone does not establish technical equivalence.',proposal='Sections 5.2 and 5.3: one-family internal-history and comparable benchmarks.',limits='The provisional technical, quantity and commercial rules require BSES SME approval. Excluded observations remain visible.'),
 dict(title='Fair-value calculation',purpose='Explain the quote, historical reference, range and target in plain language.',screen='Price Benchmarking',steps=['Read Supplier quoted price, Provisional fair-value range and Recommended target.','Read the Historical reference and Potential opportunity displayed beside them.','Use The price comparison and What this means to explain the relationship.'],question='What is the fair price?',expected='A calculated historical range and target, or an explicit insufficient-evidence result without an invented target.',say='The band summarizes eligible historical evidence. The target is a proposed negotiation position under a transparent, versioned method.',proposal='Section 5.3: defensible fair-value assessment with confidence and limitations.',limits='The quantile method is provisional, not a calibrated confidence interval or guaranteed market price. No unsupported FX, freight or index adjustment is inferred.'),
 dict(title='Supplier intelligence',purpose='Put the quotation in its relevant supplier context.',screen='Supplier & Evidence',steps=['Read Supplier context and the historical delivery and quality observations.','Read the source and observation date below the supplier facts.','Read Evidence reliability before interpreting any concern.'],question='What information is missing?',expected='Only the selected supplier’s relevant available records and explicit limitations.',say='Supplier performance supports procurement preparation. Internal quality or delivery observations are different from official legal findings.',proposal='Section 6: supplier context embedded in the same agent, with separate source attribution.',limits='Suppliers are fictional in this demo. Missing official evidence does not imply sanctions, debarment or legal disqualification.'),
 dict(title='AI chatbot',purpose='Let a manager ask ordinary case questions without technical prompts.',screen='AI Negotiation Chat',steps=['Confirm the selected procurement case.','Click a suggested question, or enter a question and click Send question.','Click a cited historical record to open Supplier & Evidence.'],question='Why is this supplier expensive?',expected='A case-linked explanation using the actual saved quotation, range, target and relevant evidence.',say='The assistant explains this case and shows its sources. Its financial answers come from the pricing engine.',proposal='Sections 4.2 and 5: explainable recommendations and source-linked negotiation support.',limits='Without an approved configured LLM, this is a limited deterministic assistant supporting predefined questions. Optional AI routing is constrained and live connectivity is not verified.'),
 dict(title='Negotiation recommendations',purpose='Demonstrate useful preparation and a safe what-if scenario.',screen='AI Negotiation Chat',steps=['Click What questions should we ask the supplier? to see challenge points and conditional concessions.','Click What if the supplier reduces its quote by 5%?','Read the hypothetical revised unit price and remaining opportunity against the existing target.'],question='What price should we negotiate?',expected='A justified advisory target and a decimal-safe scenario; the stored quotation and benchmark remain unchanged.',say='We can ask evidence-backed questions and test a quotation reduction before negotiation. The scenario does not record savings or make a procurement decision.',proposal='Sections 5.1 and 5.4: targets, challenge points, questions and concession strategies.',limits='No automatic counteroffer, supplier approval or contract award is available. Walk-away policy is not approved.'),
 dict(title='Evidence Cards',purpose='Make the recommendation independently inspectable.',screen='Supplier & Evidence → Evidence Card',steps=['Read the analysis identifier, captured timestamp and conclusion.','Open Technical Details for snapshot, rule, original values and normalization formulas.','Expand the full comparable set and exclusion reasons as needed.'],question='Show the evidence.',expected='The exact persisted case result, linked source observations, transformation calculations and review history.',say='This card connects the conclusion to its inputs. A reviewer can challenge the eligible records and reproduce the calculation.',proposal='Section 4.2: source, timestamp, authentication context, transformations, comparables, confidence and approval history.',limits='Technical lineage is preserved. Real-source authentication, approved methodology and independent BSES review remain outstanding.'),
 dict(title='Negotiation Pack generation',purpose='Produce a shareable internal review document.',screen='Reports & Validation',steps=['Click Download Negotiation Pack. The browser downloads a PDF for the selected saved analysis.','Open Earlier report versions to retrieve an archived export.','The same action is available as Generate Negotiation Pack in benchmarking, evidence or chat.'],question='Generate a Negotiation Pack.',expected='A versioned PDF containing prices, comparable evidence, supplier context, limitations and review status.',say='The pack comes from persisted calculations and evidence, not reconstructed model memory.',proposal='Section 5.4: approval-ready negotiation packs with one-page summary and evidence.',limits='Exports are restricted by role and remain clearly synthetic. An exported recommendation is not an award or contractual acceptance.'),
 dict(title='Historical validation',purpose='Show whether the benchmark is defensible against withheld outcomes.',screen='Reports & Validation → Historical validation',steps=['Read the completed synthetic holdout count, band coverage and retained failures.','Expand View validation results and failures.','Reviewer, evaluator or admin users can click Open full validation workspace to lock predictions before revealing outcomes.'],question='How reliable is the evidence?',expected='Actual persisted historical test results, including failures and reviewer findings. No completed result is invented.',say='We test the benchmark before revealing the historical award. Failed cases are retained so reviewers can assess limitations.',proposal='Sections 7.1 and 8.2: 8–12 eligible blinded cases, variance, failures and independent review.',limits='The seed contains ten synthetic holdouts. Results are role-restricted; no completed evaluation is shown if none has run. BSES error thresholds and real-data credibility acceptance are pending.'),
 dict(title='Human approval and audit',purpose='Show that authority remains with procurement reviewers.',screen='Reports & Validation → Review status',steps=['During the guided tour, read the review explanation; no decision is submitted. Click Exit to leave the tour.','An authorized user can expand Human review actions, choose an available Review action, enter Reason for the decision and click Record internal review.','Reviewer/admin users can click View audit records for the detailed integrity-checked history.'],question='How does human review work?',expected='A reasoned internal workflow transition tied to an exact analysis, plus an audit record. Unauthorized actions remain blocked.',say='People review the recommendation. Internal acceptance does not create a PO, approve a supplier, award a tender or change SAP/SRM.',proposal='Sections 8 and 9: human authority, approval history, governance and traceability.',limits='The pilot role model is not enterprise SSO. An internal case status is not a signed M0, M1, M2 or M3 milestone.'),
 dict(title='Final demonstration summary',purpose='Close with the business value and the remaining decisions.',screen='Dashboard, then Reports & Validation',steps=['Summarize the quotation, supported historical range, target and relevant evidence.','Confirm that a Negotiation Pack can be downloaded and failed tests remain available.','Finish or Exit the guided demo. Use Manager Demo Guide in the sidebar for this document.'],question='What should the procurement reviewer do next?',expected='A coherent evidence-led preparation workflow with clear human decision boundaries.',say='We have shown one agent moving from procurement evidence to a reviewable negotiation position. The next step is BSES-approved data and independent business validation.',proposal='Sections 7–13: one-family credibility pilot followed by gated productization.',limits='No contractual acceptance is claimed. Real data, policy approval, source rights, live-provider verification, PostgreSQL verification, security/UAT and signed gates remain pending.')
]
TOPICS.insert(3, dict(title='Data Sources and Public Market Evidence',purpose='Distinguish public context from synthetic pricing inputs.',screen='Data Sources, then Price Benchmarking > External Market References',steps=[
'Open Data Sources. The three source cards show recorded availability. Use Check availability to refresh it, or Open Original Source to view the external website.',
'GeM: https://gem.gov.in/ - procurement context only; no exact listing or GeM API price is verified.',
'KEI third-party copy: https://www.scribd.com/document/1070412982/KEI-Cable-List-Price-13th-Mar-2026 - Third-party published price-list copy - authenticity and comparability pending. This is not an official live KEI API. Sign-in or subscription restrictions may apply.',
'Technical document: https://cdnbbsr.s3waas.gov.in/s303412aef4dcdee4f934f7bf599f89783/uploads/2025/06/202506302010749769.pdf - Government-hosted technical specification - not price evidence. The publisher is Uttarakhand Power Corporation Ltd., replacing the prior NFL document.',
'Review PDF pages 9-11: the scope includes 11 kV aluminium three-core XLPE cable, including 95 sq. mm. The synthetic case does not confirm armour, sheath, voltage class or standards. Source Comparison shows Not directly comparable until required details are validated.',
'Expand Provenance and validation for the previous Raj Electricals URL (HTTP 404) and NFL URL (HTTP 500), retained with original verification results. New links returned HTTP 200 at review; accessibility does not authenticate prices.',
'Open External Market References and the Evidence Card. Synthetic prices were not extracted from these references. No public price is verified; the benchmark, target and historical dataset remain unchanged.'
],question='Where does the pricing data come from?',expected='Three source cards, current links, historical provenance and zero verified public price observations.',say='The procurement dataset is synthetic. Public sources support separately attributed context and technical requirements. No generated price is a real market observation.',proposal='Evidence authenticity, source provenance and technical comparability.',limits='External websites may fail, restrict access or redirect. Availability checks show clear errors and are cached for five minutes. Neither HTTP 200 nor a title date authenticates a price or effective date. No verified public price or live procurement-price API connection exists.'))

SEQUENCE=[('1 minute','Introduce the project and Dashboard; click Start Guided Demo.'),('2 minutes','Explain the quotation, historical reference, fair-value range and target.'),('2 minutes','Use the suggested expensive-quote, strategy and 5% reduction questions.'),('1 minute','Open Supplier & Evidence; show five comparables and the Evidence Card.'),('1 minute','Download the Negotiation Pack; explain human review without submitting a decision.'),('1 minute','Show completed historical validation, retained failures and the pending BSES approvals.')]

def build():
 md=['# BSES × AIONOS Manager Demo Guide','', 'A practical guide to demonstrating the existing Procurement Negotiation Intelligence application. This guide uses the six-section interface and a clearly labeled synthetic dataset.','', '## Before you begin','', '- Open http://127.0.0.1:8000 and sign in with an authorized demo account. Use the locally configured password; do not disclose it during a presentation.','- An administrator must prepare the synthetic dataset in Settings / Administration → Administration → Initialize synthetic demonstration if it has not been initialized.','- Use the admin demo role for the full walkthrough, or disclose role restrictions. Keep the walkthrough in synthetic mode.','- The backend retains forty seeded observations, ten holdouts and five original demonstration cases. Only five relevant comparables are shown by default.','', '## Recommended eight-minute demonstration','']
 md += [f'- **{duration}:** {action}' for duration,action in SEQUENCE]
 for i,t in enumerate(TOPICS,1):
  md += ['',f'## {i}. {t["title"]}','',f'**Purpose:** {t["purpose"]}',f'**Open:** {t["screen"]}','', '**Steps:**','']+[f'{n}. {step}' for n,step in enumerate(t['steps'],1)]+['',f'**Suggested question:** “{t["question"]}”',f'**Expected output:** {t["expected"]}',f'**What to say:** “{t["say"]}”',f'**Proposal link:** {t["proposal"]}',f'**Disclose:** {t["limits"]}']
 md += ['', '## One-page quick-reference sheet','', '| Topic | Open / action |','|---|---|']+[f'| {i}. {t["title"]} | {t["screen"]} |' for i,t in enumerate(TOPICS,1)]
 md += ['', '**Tour controls:** Back revisits a step. Next advances. Skip moves past the current explanation. Exit leaves the walkthrough. Finish demo ends the last step. Suggested chat questions at steps 7 and 8 are submitted automatically once; they only read the case and append an assistant audit event.','', '**Always disclose:** DEMO / SYNTHETIC; provisional methodology; opportunity is not realized savings; limited deterministic assistant without an approved AI configuration; human decisions; no production or contractual acceptance.','', '**If something is unavailable:** Prepare synthetic evidence through an administrator, calculate an unanalysed draft in Price Benchmarking, or use an authorized role. Do not present missing data or unavailable live AI as a successful result.']
 (ROOT/'BSES_MANAGER_DEMO_GUIDE.md').write_text('\n'.join(md)+'\n')
 styles=getSampleStyleSheet();styles.add(ParagraphStyle('Brand',fontName='Helvetica-Bold',fontSize=24,leading=30,textColor=colors.HexColor('#153353'),spaceAfter=14));styles.add(ParagraphStyle('GuideBody',fontSize=9,leading=12.5,textColor=colors.HexColor('#3f546e'),spaceAfter=5));styles.add(ParagraphStyle('Topic',fontSize=15,leading=19,textColor=colors.HexColor('#153353'),spaceAfter=9));styles.add(ParagraphStyle('Eyebrow',fontSize=8,leading=11,textColor=colors.HexColor('#4878b3'),spaceAfter=8))
 story=[]
 def p(text,style='GuideBody'):return Paragraph(escape(str(text)),styles[style])
 story += [p('BSES x AIONOS','Brand'),p('Manager demonstration guide','Title'),p('PROCUREMENT NEGOTIATION INTELLIGENCE','Eyebrow'),Spacer(1,10),p('A simple, evidence-led walkthrough for a nontechnical manager.'),p('Restricted synthetic pilot | Six primary sections | Human decision authority'),Spacer(1,25),p('Before you begin','Heading2')]
 for text in ['Open http://127.0.0.1:8000 and sign in with an authorized demo account. Use the admin demo role to demonstrate all review and validation views.','If no demo exists, an administrator opens Settings / Administration > Administration > Initialize synthetic demonstration.','Click Start Guided Demo. It selects the primary synthetic cable case and explains twelve steps. No review decision is submitted by the tour.','Optional AI is not required. Without approved configuration, the assistant is clearly labeled limited deterministic support.']:
  story += [p(text),Spacer(1,5)]
 story += [Spacer(1,16),p('Recommended eight-minute sequence','Heading2')]
 for duration,action in SEQUENCE:story += [p(f'{duration} - {action}'),Spacer(1,5)]
 story += [Spacer(1,20),p('Disclosure for every presentation','Heading2'),p('Synthetic data. Provisional pricing rules. Potential opportunity is not realized savings. No autonomous procurement action or contractual acceptance.'),PageBreak()]
 for offset in range(0,len(TOPICS),2):
  for i,t in enumerate(TOPICS[offset:offset+2],offset+1):
   block=[p(f'TOPIC {i:02d}','Eyebrow'),p(t['title'],'Topic'),p('Purpose: '+t['purpose']),p('Open: '+t['screen'])]
   for n,step in enumerate(t['steps'],1):block.append(p(f'{n}. {step}'))
   for title,key in [('Suggested question','question'),('Expected output','expected'),('What to say','say'),('Proposal link','proposal'),('Disclose','limits')]:block.append(p(title+': '+t[key]))
   story += [KeepTogether(block)]
   if i==offset+1: story.append(Spacer(1,18))
  story.append(PageBreak())
 story += [p('One-page quick reference','Brand'),p('Keep this page beside the application during your presentation.','GuideBody'),Spacer(1,10)]
 rows=[[p('Topic','Eyebrow'),p('Menu / action','Eyebrow')]]+[[p(f'{i}. {t["title"]}'),p(t['screen'])] for i,t in enumerate(TOPICS,1)]
 table=Table(rows,colWidths=[205,310],hAlign='LEFT');table.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#edf3fc')),('LINEBELOW',(0,0),(-1,-1),.3,colors.HexColor('#dce5ef')),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]));story += [table,Spacer(1,20),p('Tour controls','Heading2'),p('Back: revisit. Next: advance. Skip: move on. Exit: leave the walkthrough. Finish demo: end the last step.'),p('Chat shortcuts','Heading2'),p('Why is this supplier expensive? | What price should we negotiate? | Compare historical purchases. | What if the supplier reduces its quote by 5%? | Show the evidence. | Generate a Negotiation Pack.'),Spacer(1,10),p('Always disclose','Heading2'),p('DEMO / SYNTHETIC. Provisional methodology. Opportunity is not savings. Limited deterministic assistant without approved AI configuration. Human decisions. BSES acceptance pending.')]
 def footer(canvas,doc):
  canvas.setStrokeColor(colors.HexColor('#d9e3ef'));canvas.line(40,35,555,35);canvas.setFont('Helvetica',8);canvas.setFillColor(colors.HexColor('#6a7f98'));canvas.drawString(40,23,'BSES x AIONOS | Manager guide | Restricted synthetic pilot');canvas.drawRightString(555,23,str(doc.page))
 SimpleDocTemplate(str(ROOT/'BSES_MANAGER_DEMO_GUIDE.pdf'),pagesize=(595,842),leftMargin=40,rightMargin=40,topMargin=38,bottomMargin=48).build(story,onFirstPage=footer,onLaterPages=footer)
 print('Created manager Markdown/PDF guide with fourteen topics and one-page quick reference.')
if __name__=='__main__':build()
